pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address embeddedOwner) public {
        // Admissible domain: the embedded owner must be a real (nonzero) address
        vm.assume(embeddedOwner != address(0));

        // Build an owner() call whose calldata mimics a clone invocation:
        // 4-byte selector + one 32-byte word + 2-byte little-endian length (34).
        // Immutable-args offset = 38 - (34 + 2) = 2.
        // owner() = shr(0x60, calldataload(2)) -> bytes 10..29 of the appended word.
        bytes memory arg = new bytes(32);
        // place embeddedOwner at bytes 10..29 of the word
        for (uint256 i = 0; i < 20; i++) {
            arg[10 + i] = bytes20(embeddedOwner)[i];
        }
        bytes memory data = abi.encodePacked(C.owner.selector, arg, uint16(34));

        (bool ok, bytes memory ret) = address(c).call(data);
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (address)) == embeddedOwner);
    }
}

