pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a) public {
        // Admissible domain: owner() reads the immutable arg at calldata offset
        // (calldatasize - 2 - low16(a)) = (36 - 2 - 0x22) = 0, so the arg read
        // by the reference is exactly the top 20 bytes of the calldata word == a.
        // Keep a nonzero so the mutant's out-of-bounds read (returns 0) is caught.
        vm.assume(a != address(0));
        vm.assume(uint160(a) & 0xffff == 0x22);

        // Drive c through `owner`: send calldata selector ++ a (owner takes no
        // declared args, but reads its raw calldata for immutable args).
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.owner.selector, a)
        );

        // General rule: the reported owner equals the address word embedded at
        // immutable-arg offset 0x0 (here: a). The mutant reads offset 0x3c,
        // past the end of calldata, yielding address(0) != a.
        assertTrue(ok && abi.decode(ret, (address)) == a);
    }
}

