pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a) public {
        vm.assume(a != address(0));

        // Build clone-style calldata: 4-byte owner() selector + 64 bytes of
        // appended immutable args. The embedded address sits at arg offset 0x0
        // (calldata bytes 16..35). Trailing two bytes = 0x0032 (50), so the
        // immutable-args offset = 68 - 50 - 2 = 16, i.e. the args start at
        // calldata byte 16, exactly where the address word begins.
        bytes memory cd = new bytes(68);
        bytes4 sel = c.owner.selector;
        for (uint256 i = 0; i < 4; i++) cd[i] = sel[i];
        for (uint256 i = 0; i < 20; i++) cd[16 + i] = bytes32(uint256(uint160(a)))[i + 12];
        cd[66] = 0x00;
        cd[67] = 0x32;

        (bool ok, bytes memory ret) = address(c).call(cd);
        assertTrue(ok);
        assertTrue(ret.length == 32);
        address returned = abi.decode(ret, (address));

        // General rule: owner() returns the address stored at immutable-arg offset 0x0.
        assertTrue(returned == a);
    }
}

