pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address ownerArg, address debtArg) public {
        // Build clone-style calldata: selector + two 32-byte immutable arg words + uint16 length (64)
        bytes memory payload = abi.encodePacked(
            C.owner.selector,
            abi.encode(ownerArg, debtArg),
            bytes2(0x0040)
        );

        (bool ok, bytes memory ret) = address(c).call(payload);
        assertTrue(ok, "owner() call must not revert");

        address returned = abi.decode(ret, (address));
        // General rule: owner() returns the first immutable arg (offset 0x0),
        // regardless of what the other arg words contain.
        assertTrue(returned == ownerArg, "owner() must return the owner arg at offset 0x0");
    }
}

