pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory, ERC20} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address collateralToken, address debtToken) public {
        // Keep the domain wide: any two distinct non-zero addresses are admissible.
        vm.assume(collateralToken != address(0));
        vm.assume(debtToken != address(0));
        vm.assume(collateralToken != debtToken);

        // The factory deploys a clone of C with immutable args packed as:
        // owner @0x00, collateral @0x14, debt @0x28, factory @0x3c.
        address cooler = factory.generateCooler(ERC20(collateralToken), ERC20(debtToken));
        vm.assume(cooler != address(0));

        // General rule: collateral() must always report the token stored at
        // immutable-arg offset 0x14 (the collateral token). The mutant reads
        // offset 0x28 and returns the debt token instead, violating this
        // for every input where collateralToken != debtToken.
        assertTrue(C(cooler).collateral() == ERC20(collateralToken));
    }
}

